create table if not exists public.subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, plan text not null default 'monthly', status text not null default 'pending' check(status in ('pending','active','expired','cancelled')), started_at timestamptz, expires_at timestamptz, payment_reference text, provider_metadata jsonb not null default '{}'::jsonb, activation_method text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.subscriptions add column if not exists plan text default 'monthly'; alter table public.subscriptions add column if not exists status text default 'pending'; alter table public.subscriptions add column if not exists started_at timestamptz; alter table public.subscriptions add column if not exists expires_at timestamptz; alter table public.subscriptions add column if not exists payment_reference text; alter table public.subscriptions add column if not exists provider_metadata jsonb default '{}'::jsonb; alter table public.subscriptions add column if not exists activation_method text; alter table public.subscriptions add column if not exists created_at timestamptz default now(); alter table public.subscriptions add column if not exists updated_at timestamptz default now();
